// === Tab: mySketch ===
setup = function() {
	size(400,400);
	background(0);
	loadPixels();
    var px=this.imageData.data,bpx;
    if (true) { bpx=px.slice(0); }
	angleMode = "radians";
	var scaling = 0.8,
		e = [],
		s = 150,
		pn = 100,
		a = (s * 2) / pn,
		ps = ceil(a * 1.2),
		r = ~~random(0, 10e6);
	var getNoC = function(y) {

		if (y >= 22) {
			return color(0, 76, 102);
		}
		if (y >= 4) {
			return color(222, 188, 17);
		}
		if (y >= -20) {
			return color(0, 255, 0);
		}
		if (y >= -50) {
			return color(145, 145, 145);
		}
		return color(255, 255, 255);

	};
	var E = [];
	for (var i = 0; i < pn; i++) {
		E.push([]);
	}

	var _Y = 0;
	for (var Y = -s; Y < s; Y += a) {
		var _X = 0;
		for (var X = -s; X < s; X += a) {
			var n = map(noise((X + r) / 120, (Y + r) / 120), 0, 1, -250, 250);
			n += dist(X, Y, -0, 0) * 0.1;
			E[_Y][_X] = {
				x: ~~X,
				y: ~~0 + (n * 1),
				z: Y + random(),
				c: getNoC(n)
			};
			var c = E[_Y][_X].c;
			if (_Y === 0 || _Y === pn - 1 || _X === 0 || _X === pn - 1) {
				c = color(1);
			} else
			if (E[_Y][_X].y < 22) {
				if (_Y < pn - 1 && _Y !== 0) {
					var sh = ((E[_Y - 1][_X].y) - (E[_Y][_X].y)) * 0.15;
					c = lerpColor(c, 0, constrain(sh, 0, 0.7));
					c = lerpColor(c, -1, constrain(-sh, 0, 0.6));
				}
			} else
			if (E[_Y][_X].y <= 45) {
				if (_Y < pn - 1 && _Y !== 0) {
					c = lerpColor(color(0, 192, 255), 0, constrain(-map(E[_Y][_X].y, 0, 28, 1, 0), 0, 0.6));
				}
			} else
			if (E[_Y][_X].y <= 60) {
				c = color(1);
			}
			E[_Y][_X].c = blue(c) << 16 | green(c) << 8 | red(c);
			_X++;
		}
		_Y++;
	}

	var i = 0;
	for (var Y = 0; Y < pn; Y++) {
		for (var X = 0; X < pn; X++) {
			E[X][Y].y = constrain(E[X][Y].y, -1000, 23);
			if (E[X][Y].c !== 6704128) {
				e[i] = E[X][Y];
				i++;
			}
		}
	}
	var aa = 0;
	frameRate(60);
	this.draw = function() {
		px.set(bpx);
		var ts = 0.01 + map(this.__frameRate, 0, 60, 0, 0.01);
		var r = ps * scaling,
			yaw = ts,
			pitch = 0;

		scaling = constrain(scaling, 0.5, 3);
		var sx = sin(yaw),
			cx = cos(yaw),
			sy = sin(pitch),
			cy = cos(pitch);
            aa += yaw;
            if(round(aa%1.5)===1){
                aa=0;
                e = e.sort(function(av, bv) {
                    return (av.z - bv.z);
                });
            }
		var lb = 0,rb = 0,l = 0;
		for (var j in e) {
			var i = j;
			var x = e[i].x,
				y = e[i].y,
			z = e[i].z;
			x = x * cx + z * sx;
			z = z * cx - e[i].x * sx;
			y = y * cy + z * sy;
			z = z * cy - e[i].y * sy;
			e[i].x = x;
			e[i].y = y;
			e[i].z = z;
			c = e[i].c;
			x = ~~(200 + x * scaling);
			y = ~~((-z / 2) + 200 + y * scaling);
			l |= 0;
			rb |= 0;
			lb |= 0;
			rb = x + r;
			if (rb > 400) {
				rb = 400;
			}
			lb = x;
			if (lb < 0) {
				lb = 0;
			}
			for (var k = lb; k < rb; k++) {
				var _y = 0;
				l = k + y * 400 << 2;
				while (_y < 100) {
					if ( px[l + 1] !== 0) {
						_y = 1000;
					} else {
						px[l] = c & 255;
						px[l + 1] = c >> 8 & 255;
						px[l + 2] = c >> 16 & 255;
					}
					_y++;
					l += 1600;
				}
			}
		}
		updatePixels();
		fill(255, 0, 0);
		text(~~this.__frameRate, 10, 10);
	};
};
setup();

